// BotForge signs every call: hex HMAC-SHA256 over "<timestamp>." + the raw body, using
// N8N_WEBHOOK_SIGNING_SECRET (apps/api/app/integrations/n8n_client.py sign()/verify_callback()).
// Fails CLOSED: no secret configured, missing headers, stale timestamp or bad MAC => rejected.
const crypto = require('crypto');
const item = $input.first();
const reject = (reason) => [{ json: { verified: false, reason } }];
const secret = $env['N8N_WEBHOOK_SIGNING_SECRET'] || '';
if (!secret) return reject('signing secret is not configured on this n8n');
const h = item.json.headers || {};
const sig = String(h['x-botforge-signature'] || '');
const ts = String(h['x-botforge-timestamp'] || '');
if (!sig || !ts) return reject('missing signature headers');
if (!/^\d{1,12}$/.test(ts) || Math.abs(Date.now() / 1000 - Number(ts)) > 300) return reject('stale or malformed timestamp');
if (!item.binary || !item.binary.data) return reject('raw body unavailable (Webhook option rawBody must be on)');
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = crypto.createHmac('sha256', secret).update(ts + '.').update(raw).digest('hex');
const a = Buffer.from(expected, 'utf8');
const b = Buffer.from(sig, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return reject('bad signature');
return [{ json: { ...item.json, verified: true } }];

// DEMO FIXTURE - every name, id, price, doctor, slot and order in this workflow is fictional demo data.
// State (bookings, counters) lives in n8n workflow static data and is NOT part of this export.
const body = $input.first().json.body || {};
const a = body.args || {};
const S = $getWorkflowStaticData('global');
S.bookings = S.bookings || {};
S.counter = S.counter || 0;
const need = (fields) => fields.filter((f) => a[f] === undefined || a[f] === null || String(a[f]).trim() === '');
const bad = (error, extra = {}) => [{ json: { ok: false, error, ...extra } }];
const nextId = (prefix) => { S.counter += 1; return prefix + '-' + String(1000 + S.counter); };
const isDate = (s) => /^\d{4}-\d{2}-\d{2}$/.test(String(s));
const isTime = (s) => /^([01]\d|2[0-3]):[0-5]\d$/.test(String(s));

const ORDERS = {
  'TF-1001': { status: 'processing', item: 'Cotton poplin, 200 m', eta: '2026-10-02' },
  'TF-1002': { status: 'dispatched', item: 'Silk blend, 60 m', eta: '2026-09-28', tracking: 'BLU-77-4521-09' },
  'TF-1003': { status: 'delivered', item: 'Linen, 120 m', delivered_on: '2026-09-18' },
  'TF-1004': { status: 'on_hold', item: 'Rayon crepe, 300 m', reason: 'payment pending' },
};
const RATES = { cotton: 185, linen: 320, silk_blend: 540, rayon: 210 };
switch (a.action) {
  case 'order_status': {
    const id = String(a.order_id || '').toUpperCase();
    if (!id) return bad('missing fields: order_id');
    const o = ORDERS[id] || (S.bookings[id] && S.bookings[id].kind === 'quote' ? { status: 'quote_received', ...S.bookings[id] } : null);
    if (!o) return bad('no order found for that id');
    return [{ json: { ok: true, order_id: id, ...o } }];
  }
  case 'request_bulk_quote': {
    const m = need(['company', 'contact_phone', 'fabric_type', 'quantity_meters']); if (m.length) return bad('missing fields: ' + m.join(', '));
    if (!(a.fabric_type in RATES)) return bad('unknown fabric_type', { fabric_types: Object.keys(RATES) });
    const qty = Number(a.quantity_meters); if (!(qty >= 50)) return bad('bulk quotes start at 50 metres');
    const disc = qty >= 1000 ? 0.15 : qty >= 300 ? 0.08 : 0;
    const per = Math.round(RATES[a.fabric_type] * (1 - disc) * 100) / 100;
    const id = nextId('VQ');
    S.bookings[id] = { id, kind: 'quote', company: a.company, contact_phone: a.contact_phone, email: a.email || null, fabric_type: a.fabric_type, quantity_meters: qty, per_meter_inr: per, total_inr: Math.round(per * qty) };
    return [{ json: { ok: true, quote_id: id, fabric_type: a.fabric_type, quantity_meters: qty, per_meter_inr: per, discount_percent: disc * 100, total_inr: Math.round(per * qty), lead_time_days: qty >= 1000 ? 14 : 7, valid_for_days: 7 } }];
  }
  default: return bad('unknown action', { valid_actions: ['order_status', 'request_bulk_quote'] });
}
